import{_ as t,c as s,o as e,ag as r}from"./chunks/framework.Cycwnjj0.js";const n="/assets/select-desired-table-for-adding-columns.DVuUT-Nk.webp",a="/assets/custom-css-button-of-your-desired-table.mIG5HvoR.webp",u="/assets/custom-code-field-update-custom-css-button.-4IQ0swE.webp",c="/assets/preview-of-custom-css.DxcpSoYF.webp",C=JSON.parse('{"title":"Custom CSS In Product/Comparison Tables","description":"","frontmatter":{},"headers":[],"relativePath":"guide/product-tables-module/custom-css-in-product-comparison-tables.md","filePath":"guide/product-tables-module/custom-css-in-product-comparison-tables.md"}'),p={name:"guide/product-tables-module/custom-css-in-product-comparison-tables.md"};function i(l,o,d,g,m,h){return e(),s("div",null,[...o[0]||(o[0]=[r('<h1 id="custom-css-in-product-comparison-tables" tabindex="-1">Custom CSS In Product/Comparison Tables <a class="header-anchor" href="#custom-css-in-product-comparison-tables" aria-label="Permalink to &quot;Custom CSS In Product/Comparison Tables&quot;">​</a></h1><p><strong>Custom CSS</strong> is a feature of AzonPress that allows you to customize the appearance of both <strong>Product Tables</strong> and <strong>Comparison Tables</strong> on your website using a markup language that controls HTML elements on a web page. This article will guide you through <strong>Using Custom CSS</strong> with <strong>AzonPress</strong> for <strong>Amazon</strong> products on your <strong>WordPress</strong> website.</p><h2 id="custom-css-in-product-tables" tabindex="-1">Custom CSS In Product Tables <a class="header-anchor" href="#custom-css-in-product-tables" aria-label="Permalink to &quot;Custom CSS In Product Tables&quot;">​</a></h2><p>To learn how to use Custom CSS to a Product table with AzonPress, follow the steps with the screenshots below –</p><p><strong>Remember</strong>, you have the option to use the <strong>Custom CSS</strong> feature on both the Product Tables and Comparison Tables. But here, I am going to show <strong>the example of using Custom CSS in a Product Table only</strong>.</p><p>First, go to <strong>Amazon Products</strong> from the <strong>WordPress Sidebar</strong> or <strong>Product Tables</strong> from the <strong>Amazon</strong> dropdown in the top right corner of the <strong>AzonPress Navbar.</strong></p><p>Now, select the desired <strong>Table</strong> where you want to use <strong>Custom CSS</strong> and click on the <strong>Pencil Icon.</strong></p><p>If you do not have any existing <strong>Product Tables</strong>, you can create a new Product Table.</p><p><img src="'+n+'" alt="Select desired table"></p><p>Click on the <strong>Custom CSS</strong> button from the top right corner and a pop-up page will appear.</p><p><img src="'+a+'" alt="Custom CSS button of your desired table"></p><p>Now, in the custom code field, you can write any Custom CSS so that the appearance of your table looks exactly according to your coding.</p><p>Each table has a <strong>Unique ID</strong> that can be used to target specifically that table.</p><p><strong>Remember</strong>, use your own Table&#39;s unique ID in your Custom CSS.</p><p>After entering the required code, click on the <strong>Update Custom CSS</strong> button to save all the changes you want to appear in your table.</p><p><img src="'+u+'" alt="Custom code field and update custom css button"></p><p>Here, you can see the <strong>Preview</strong> of the <strong>Product Table</strong> where I used the <strong>Custom CSS</strong> to <strong>change</strong> all the <strong>text color</strong> from black to red under the <strong>Price</strong> column.</p><p><img src="'+c+'" alt="Preview of Custom CSS"></p><p>That&#39;s how you can use the Custom CSS feature of AzonPress!</p><p>If you have any further questions, concerns, or suggestions, please do not hesitate to contact our support team. Thank you.</p><hr>',21)])])}const S=t(p,[["render",i]]);export{C as __pageData,S as default};
